cd /home/user/RL_Study/report-gepa/runs/originals/heat-records-map && python3 - <<'EOF'
import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    for k,v in f['tables'].items():
        env[k]=pd.read_csv(v)
    print('='*20, f['id'])
    print('SOURCE:', f['source'])
    print('CLAIM:', f['claim'])
    try:
        val=eval(f['code'], {'__builtins__':{}}, env)
        print(val)
    except Exception as e:
        print('ERROR',type(e),e)
EOF

